// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";
import {CoolerFactory} from "../src/Cooler.sol";
import {ERC20} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    CoolerFactory factory;
    ERC20 collateralToken;
    ERC20 debtToken;

    function setUp() public {
        factory = new CoolerFactory();
        collateralToken = new MockERC20("Collateral", "COL", 18);
        debtToken = new MockERC20("Debt", "DBT", 18);
    }

    function testFuzz_property(address owner, uint8 collDecimals, uint8 debtDecimals) public {
        vm.assume(owner != address(0));
        vm.assume(owner != address(factory));
        vm.assume(collDecimals <= 18);
        vm.assume(debtDecimals <= 18);

        ERC20 coll = new MockERC20("Collateral", "COL", collDecimals);
        ERC20 debt = new MockERC20("Debt", "DBT", debtDecimals);

        vm.prank(owner);
        address cooler = factory.generateCooler(coll, debt);
        c = Cooler(cooler);

        address actualOwner = c.owner();
        assertTrue(actualOwner == owner);
    }
}

contract MockERC20 is ERC20 {
    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_, decimals_) {}
}
